import type { NativeStackScreenProps } from '@react-navigation/native-stack';
// The same package the web app imports. One definition of an order, three uses.
import { orderId, type OrderId } from '@acme/core/schemas';

export type RootStackParamList = {
  Orders: undefined;
  OrderDetail: { id: OrderId; from?: 'push' | 'deeplink' };
};

export type OrderDetailProps = NativeStackScreenProps<
  RootStackParamList,
  'OrderDetail'
>;

// navigation.navigate('OrderDetail', { id: 42 }) does not compile: id is a
// branded OrderId, not any string or number that happens to be lying around.

export const linking = {
  prefixes: ['acme://', 'https://acme.example'],
  config: {
    screens: {
      Orders: 'orders',
      OrderDetail: {
        path: 'orders/:id',
        // Deep links and push payloads arrive as untrusted strings. Parsing
        // both through the shared schema is what stops the two drifting.
        parse: { id: (raw: string) => orderId.parse(raw) },
        stringify: { id: (value: OrderId) => value },
      },
    },
  },
} as const;
